set -e
az account set --subscription "$SUBSCRIPTION_ID"
python3 << 'PYEOF'
import os, sys, subprocess, time, urllib.request

def download():
    url = os.environ['PACKAGE_URI']
    for attempt in range(5):
        try:
            with urllib.request.urlopen(url, timeout=60) as resp, open('package.zip', 'wb') as f:
                f.write(resp.read())
            return
        except Exception as e:
            print(f'Download attempt {attempt + 1} failed: {e}')
            time.sleep(10)
    raise SystemExit('Package download failed after 5 attempts')

def wait_for_scm():
    app = os.environ['APP_NAME']
    url = f'https://{app}.scm.azurewebsites.net'
    for _ in range(30):
        try:
            urllib.request.urlopen(url, timeout=5)
            return
        except Exception:
            time.sleep(5)

def deploy():
    rg = os.environ['RESOURCE_GROUP']
    app = os.environ['APP_NAME']
    cmd = ['az', 'functionapp', 'deployment', 'source', 'config-zip', '--resource-group', rg, '--name', app, '--src', 'package.zip']
    attempts = 8
    for attempt in range(attempts):
        try:
            subprocess.run(cmd, timeout=300, check=True)
            return
        except subprocess.TimeoutExpired:
            print(f'Deployment attempt {attempt + 1} timed out after 300s')
        except subprocess.CalledProcessError as e:
            print(f'Deployment attempt {attempt + 1} failed with exit code {e.returncode}')
        if attempt < attempts - 1:
            time.sleep(30)
    raise SystemExit(f'Deployment failed after {attempts} attempts')

download()
wait_for_scm()
deploy()
PYEOF
